samples.content:
targetScope = 'local'

@description('Name of the storage account to manage.')
param storageAccountName string

@description('Name of the blob container to create.')
param containerName string

extension storage with {
  accountName: storageAccountName
}

resource container 'BlobContainer' = {
  name: containerName
  metadata: {
    managedBy: 'bicep'
  }
}

resource settings 'Blob' = {
  containerName: container.name
  name: 'config/settings.json'
  contentType: 'application/json'
  content: string({
    environment: 'dev'
    featureFlags: [
      'search'
    ]
  })
  tags: {
    project: 'bicep-ext-storage'
  }
}

output containerUrl string? = container.url
output settingsUrl string? = settings.url

targetScope = 'local'

@description('Name of the ADLS Gen2 (hierarchical namespace) storage account to manage.')
param storageAccountName string

@description('Microsoft Entra object ID of the group granted access to the curated zone.')
param dataEngineersGroupId string

extension storage with {
  accountName: storageAccountName
}

@description('A medallion layout, with one file system per zone.')
resource bronze 'DataLakeFileSystem' = {
  name: 'bronze'
  metadata: {
    zone: 'raw'
  }
}

resource silver 'DataLakeFileSystem' = {
  name: 'silver'
  metadata: {
    zone: 'cleansed'
  }
}

resource gold 'DataLakeFileSystem' = {
  name: 'gold'
  metadata: {
    zone: 'curated'
  }
  // Default entries are inherited by directories and files created later.
  accessControl: [
    {
      type: 'User'
      permissions: 'rwx'
    }
    {
      type: 'Group'
      permissions: 'r-x'
    }
    {
      type: 'Other'
      permissions: '---'
    }
    {
      scope: 'Default'
      type: 'Group'
      id: dataEngineersGroupId
      permissions: 'r-x'
    }
    {
      scope: 'Default'
      type: 'Mask'
      permissions: 'rwx'
    }
  ]
}

resource landing 'DataLakeDirectory' = {
  fileSystemName: bronze.name
  path: 'landing/events'
  permissions: '0750'
}

resource curatedSales 'DataLakeDirectory' = {
  fileSystemName: gold.name
  path: 'sales'
  accessControl: [
    {
      type: 'User'
      permissions: 'rwx'
    }
    {
      type: 'Group'
      id: dataEngineersGroupId
      permissions: 'r-x'
    }
    {
      type: 'Other'
      permissions: '---'
    }
    {
      type: 'Mask'
      permissions: 'r-x'
    }
  ]
}

output bronzeUrl string? = bronze.url
output landingUrl string? = landing.url
output curatedSalesUrl string? = curatedSales.url

targetScope = 'local'

@description('Name of the storage account to manage.')
param storageAccountName string

@secure()
@description('Storage account shared key. Required because the table ACL API rejects Microsoft Entra tokens.')
param storageAccountKey string

extension storage with {
  accountName: storageAccountName
  accountKey: storageAccountKey
}

resource orders 'Queue' = {
  name: 'orders'
  metadata: {
    consumer: 'order-processor'
  }
}

resource ordersDeadLetter 'Queue' = {
  name: 'orders-poison'
  metadata: {
    consumer: 'order-processor'
    purpose: 'dead-letter'
  }
}

resource settings 'Table' = {
  name: 'settings'
  accessPolicies: [
    {
      id: 'readonly'
      permissions: 'r'
      start: '2026-01-01T00:00:00Z'
      expiry: '2027-01-01T00:00:00Z'
    }
  ]
}

@description('Seed configuration that the application reads at startup.')
resource orderLimits 'TableEntity' = {
  tableName: settings.name
  partitionKey: 'orders'
  rowKey: 'limits'
  entity: {
    maxItemsPerOrder: '50'
    maxOrderValue: '2500.00'
    requiresApproval: 'true'
    updatedOn: '2026-01-01T00:00:00Z'
  }
  // Values default to Edm.String, so declare the ones that need a richer type.
  entityTypes: {
    maxItemsPerOrder: 'Int32'
    maxOrderValue: 'Double'
    requiresApproval: 'Boolean'
    updatedOn: 'DateTime'
  }
}

resource orderRegions 'TableEntity' = {
  tableName: settings.name
  partitionKey: 'orders'
  rowKey: 'regions'
  entity: {
    primary: 'westeurope'
    secondary: 'northeurope'
  }
}

output ordersQueueUrl string? = orders.url
output deadLetterQueueUrl string? = ordersDeadLetter.url
output settingsTableUrl string? = settings.url

targetScope = 'local'

@description('Name of the storage account to manage.')
param storageAccountName string

extension storage with {
  accountName: storageAccountName
}

resource share 'FileShare' = {
  name: 'app-config'
  quota: 100
  accessTier: 'TransactionOptimized'
  metadata: {
    managedBy: 'bicep'
  }
}

@description('Parent directories must exist before their children, so create them in order.')
resource configDirectory 'FileShareDirectory' = {
  shareName: share.name
  path: 'config'
}

resource environmentDirectory 'FileShareDirectory' = {
  shareName: share.name
  path: '${configDirectory.path}/production'
}

resource appSettings 'FileShareFile' = {
  shareName: share.name
  path: '${environmentDirectory.path}/appsettings.json'
  contentType: 'application/json'
  content: string({
    logging: {
      level: 'Information'
    }
    features: {
      betaSearch: false
    }
  })
  metadata: {
    generatedBy: 'bicep'
  }
}

output shareUrl string? = share.url
output appSettingsUrl string? = appSettings.url

targetScope = 'local'

@description('Name of the storage account to manage.')
param storageAccountName string

extension storage with {
  accountName: storageAccountName
}

@description('Files to publish, mapped to the content type they are served with.')
var files = {
  'index.html': 'text/html'
}

resource site 'BlobContainer' = {
  name: 'public-site'
  publicAccess: 'Blob'
}

resource landingPage 'Blob' = {
  containerName: site.name
  name: 'index.html'
  contentType: files['index.html']
  cacheControl: 'public, max-age=300'
  // Uploads the file from disk rather than embedding its content in the template.
  contentBase64: loadFileAsBase64('./assets/index.html')
}

resource logs 'BlobContainer' = {
  name: 'site-logs'
  metadata: {
    retention: '30d'
  }
}

@description('Append blobs suit log-style content that is added to over time.')
resource accessLog 'Blob' = {
  containerName: logs.name
  name: 'access/current.log'
  type: 'Append'
  contentType: 'text/plain'
  content: '# access log initialised by Bicep\n'
}

@description('Archive rarely-read content to keep storage costs down.')
resource archivedPage 'Blob' = {
  containerName: logs.name
  name: 'archive/index-v1.html'
  accessTier: 'Cool'
  contentType: files['index.html']
  contentBase64: loadFileAsBase64('./assets/index.html')
}

output landingPageUrl string? = landingPage.url
output accessLogUrl string? = accessLog.url
output archivedPageUrl string? = archivedPage.url
